// Calcul du score de qualification lead
const data = $input.first().json;

let score = 0;
const weights = {
  company_size: { 'startup': 2, 'pme': 5, 'enterprise': 10 },
  budget: { 'low': 1, 'medium': 5, 'high': 10 },
  urgency: { 'low': 1, 'medium': 3, 'high': 7 },
  decision_maker: { 'yes': 8, 'influence': 4, 'no': 1 },
  industry_match: { 'perfect': 10, 'good': 6, 'average': 3 }
};

// Calcul du score
Object.keys(weights).forEach(criteria => {
  if (data[criteria] && weights[criteria][data[criteria]]) {
    score += weights[criteria][data[criteria]];
  }
});

// Qualification
let qualification = 'cold';
if (score >= 35) qualification = 'hot';
else if (score >= 20) qualification = 'warm';

// Priorité
let priority = 'low';
if (score >= 40) priority = 'high';
else if (score >= 25) priority = 'medium';

return {
  json: {
    ...data,
    lead_score: score,
    qualification_status: qualification,
    priority: priority,
    qualified_at: new Date().toISOString(),
    next_action: qualification === 'hot' ? 'immediate_contact' : 
                qualification === 'warm' ? 'nurture_sequence' : 'marketing_automation'
  }
};

// Attribution automatique du commercial
const data = $input.first().json;
const leadData = data.body || data;

// Règles d'attribution par secteur et priorité
const salesAssignment = {
  'tech': {
    'high': 'commercial_tech_senior',
    'medium': 'commercial_tech_junior',
    'low': 'marketing_automation'
  },
  'retail': {
    'high': 'commercial_retail_senior', 
    'medium': 'commercial_retail_junior',
    'low': 'marketing_automation'
  },
  'finance': {
    'high': 'commercial_finance_senior',
    'medium': 'commercial_finance_junior', 
    'low': 'marketing_automation'
  },
  'default': {
    'high': 'commercial_general_senior',
    'medium': 'commercial_general_junior',
    'low': 'marketing_automation'
  }
};

const industry = leadData.industry || 'default';
const priority = leadData.priority || 'low';
const assignedTo = salesAssignment[industry]?.[priority] || salesAssignment['default'][priority];

// Calcul du SLA (temps de réponse attendu)
const slaHours = {
  'high': 2,    // 2 heures
  'medium': 24, // 1 jour  
  'low': 72     // 3 jours
};

const responseDeadline = new Date();
responseDeadline.setHours(responseDeadline.getHours() + slaHours[priority]);

return {
  json: {
    ...leadData,
    assigned_to: assignedTo,
    assignment_date: new Date().toISOString(),
    response_deadline: responseDeadline.toISOString(),
    sla_hours: slaHours[priority],
    assignment_reason: `Industry: ${industry}, Priority: ${priority}`
  }
};

