// Génération séquence emails onboarding personnalisée
const client = $input.first().json;

const emailSequence = [
  {
    delay_hours: 0,
    template: 'welcome_email',
    subject: `Bienvenue ${client.first_name} ! Votre onboarding commence`,
    variables: {
      client_name: client.first_name,
      company: client.company,
      account_manager: client.assigned_account_manager,
      onboarding_link: `${process.env.PORTAL_URL}/onboarding/${client.id}`
    }
  },
  {
    delay_hours: 24,
    template: 'setup_guide',
    subject: 'Étape 1 : Configuration de votre compte',
    variables: {
      setup_checklist: [
        'Vérification profil entreprise',
        'Configuration préférences',
        'Import données existantes',
        'Paramétrage utilisateurs'
      ]
    }
  },
  {
    delay_hours: 72,
    template: 'training_invitation', 
    subject: 'Votre formation personnalisée est prête !',
    variables: {
      training_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
      training_type: client.package_type === 'enterprise' ? 'advanced' : 'standard',
      calendar_link: `${process.env.CALENDAR_URL}/book-training/${client.id}`
    }
  },
  {
    delay_hours: 120,
    template: 'progress_check',
    subject: 'Comment se passe votre prise en main ?',
    variables: {
      progress_survey: `${process.env.SURVEY_URL}/onboarding-feedback/${client.id}`,
      support_contact: client.assigned_account_manager
    }
  }
];

return emailSequence.map(email => ({
  json: {
    client_id: client.id,
    client_email: client.email,
    client_name: client.first_name,
    ...email,
    scheduled_for: new Date(Date.now() + email.delay_hours * 60 * 60 * 1000).toISOString()
  }
}));

