// Logique de relance progressive des factures
const invoice = $input.first().json;
const today = new Date();
const dueDate = new Date(invoice.due_date);
const daysOverdue = Math.floor((today - dueDate) / (1000 * 60 * 60 * 24));

// Définir le niveau de relance selon les jours de retard
let reminderLevel = 'none';
let emailTemplate = '';
let escalation = false;
let accountAction = 'none';

if (daysOverdue >= 1 && daysOverdue <= 7) {
  reminderLevel = 'gentle';
  emailTemplate = 'gentle_reminder';
} else if (daysOverdue >= 8 && daysOverdue <= 15) {
  reminderLevel = 'firm';
  emailTemplate = 'firm_reminder'; 
} else if (daysOverdue >= 16 && daysOverdue <= 30) {
  reminderLevel = 'urgent';
  emailTemplate = 'urgent_reminder';
  escalation = true; // Notification comptable
} else if (daysOverdue > 30) {
  reminderLevel = 'final';
  emailTemplate = 'final_notice';
  escalation = true;
  accountAction = 'suspend'; // Suspension compte
}

// Calcul des pénalités si applicable
let penalty = 0;
if (daysOverdue > 15) {
  penalty = invoice.amount * 0.02; // 2% de pénalité
}

// Historique des relances
const reminderHistory = invoice.reminder_history || [];
const lastReminder = reminderHistory[reminderHistory.length - 1];

// Vérifier si on doit envoyer une relance (pas plus d'une par jour)
let shouldSendReminder = true;
if (lastReminder) {
  const lastReminderDate = new Date(lastReminder.sent_date);
  const hoursSinceLastReminder = (today - lastReminderDate) / (1000 * 60 * 60);
  if (hoursSinceLastReminder < 24) {
    shouldSendReminder = false;
  }
}

return {
  json: {
    ...invoice,
    days_overdue: daysOverdue,
    reminder_level: reminderLevel,
    email_template: emailTemplate,
    should_send_reminder: shouldSendReminder,
    escalation_required: escalation,
    account_action: accountAction,
    penalty_amount: penalty,
    total_amount_due: invoice.amount + penalty,
    next_escalation_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
    reminder_count: reminderHistory.length
  }
};
